local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["f0006319acdf78c9"] = { "La prossima destinazione della ⟦Darkmoon Faire=Fiera di Lunacupa⟧ non è ancora stata decisa, ma quando lo sarà, tu e io saremo i primi a saperlo!", "." },
  ["f006cdd7c876eb2d"] = { "<Il Braizer of Eternal Flame attende la tua offerta.>", "." },
  ["f0091dc0638f8669"] = { "Cenarius combatte al mio fianco. Illidan siede sul suo trono nelle ⟦Outland=Terre Esterne⟧, a rimuginare. Temo che la sconfitta contro Arthas sia stata il suo punto di rottura. La follia lo ha avvolto, Remulos. Rivive quegli eventi nella sua mente mille volte al giorno, ma nella sua mente è lui il vincitore e Arthas è sconfitto del tutto. Si è spinto troppo oltre, vecchio amico. Temo che presto possa arrivare il momento in cui il nostro legame sarà messo alla prova, e non sarà più come al Pozzo di Zin-Azshari.", "." },
  ["f013540964defa48"] = { "Come osi?!", "." },
  ["f020b9e3c06d275a"] = { "Scopriamolo.", "." },
  ["f0237f30298d9fed"] = { "Goblin infami... qualsiasi cosa per una moneta d'oro.", "." },
  ["f02789a1637632d0"] = { "La minaccia principale di cui Thrall vuole che ci si occupi sono le ⟦Burning Blade=Lame Ardenti⟧: membri dell'⟦Horde=Orda⟧ che hanno giurato fedeltà ai demoni. Vogliono praticare la loro magia oscura e si curano poco della visione di Thrall per il futuro dell'⟦Horde=Orda⟧ qui a Kalimdor.", "." },
  ["f02972a8933e6be6"] = { "Jin'rokh, i miei ⟦Zandalar Vindicator's Armguards=Bracciali Foderati del Vendicatore degli Zandalari⟧ sono spariti. Ne hai un paio di scorta?", "." },
  ["f02ae5a75746e775"] = { "Salute, {class}: sono un ufficiale degli encomi e opero per conto della tribù ⟦Darkspear=Lanciascura⟧. Il mio compito è assistere gli avventurieri che hanno ricevuto Anelli d'Encomio dell'⟦Horde=Orda⟧.\n\nAccetto anelli in quantità diverse, ma lo scambio più vantaggioso per te è consegnarne dieci alla volta. Quando mi consegnerai gli anelli, registrerò le tue gesta nei nostri archivi. Così otterrai la riconoscenza della tribù ⟦Darkspear=Lanciascura⟧ per il tuo impegno e il tuo servizio.", "." },
  ["f02f36dc159feff7"] = { "Viaggiatori e avventurieri, correte alla piazza della città e approfittate dei meravigliosi prezzi di Antonio! Venite, venite tutti!", "." },
  ["f031205a4d22b392"] = { "Sia noto a tutti che {name}, {class} dell'⟦Alliance=Alleanza⟧, si è <guadagnato/guadagnata> l'eterno rispetto di ⟦Ironforge=Forgiardente⟧ e dell'intera ⟦Alliance=Alleanza⟧. Ha condotto una grande opera diplomatica con il ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧ e ha compiuto azioni valorose per loro a nome nostro. Ha fatto ben più di quanto il dovere richiedesse. Tre urrà per {name}, <un/una> <vero/vera> <eroe/eroina> dell'⟦Alliance=Alleanza⟧!", "." },
  ["f03be98becb236dd"] = { "Se vuoi imparare la Scuoiatura, ti conviene andare a Old Town e passare dal Protective Hide.", "." },
  ["f03e217d6eb0b826"] = { "Vieni a parlare con me, e ciò che un tempo era torbido diventerà chiaro come il cristallo.", "." },
  ["f04855d6e880bdf6"] = { "Zug zug, <valoroso/valorosa> {class}! Ho i lupi da cavalcatura di miglior razza che tu possa desiderare. Da nessuna parte troverai un altro animale con la resistenza e l'istinto di sopravvivenza del lupo! Prego, esaminali tu stess<o/a>.", "." },
  ["f04e3c67e915df1b"] = { "Vieni, fai un viaggio nelle meravigliose, splendide giungle tropicali di Rovotorto. Proprio così, anche tu puoi passare il tempo a prendere il sole vicino ad acque cristalline, mentre io me ne sto qui in questo caldo insopportabile senza nient'altro da guardare tutto il giorno che mio fratello Frezza! Buon viaggio!", "." },
  ["f06164c35ddf7399"] = { "Hai trovato un Prairie Stalker?", "." },
  ["f08269d79131f371"] = { "%s torna al lavoro, ignaro di tutto ciò che lo circonda.", "." },
  ["f0840f3b205ca8a4"] = { "Indietro, e tenete la linea! Non possiamo fallire, o tutto sarà perduto!", "." },
  ["f09bc1cdde31bfd8"] = { "Ti preghiamo di pazientare, chiameremo il tuo nome quando sarà il tuo turno. Aiutiamo le persone nell'ordine in cui compaiono sul nostro schermo. {name}!", "." },
  ["f0a982cd3dbcc48a"] = { "Cosa posso fare?", "." },
  ["f0adfac52a8eae3f"] = { "Cosa bisogna fare?", "." },
  ["f0b1eb4e9aeb411f"] = { "%s va su tutte le furie!", "." },
  ["f0b92989bbac2be7"] = { "Come mio fratello, onoro chi onora i propri antenati. È per me una grande gioia condividere i miei segreti artigianali con i discepoli della Celebrazione della Luna!", "." },
  ["f0ba0fccf017f2e4"] = { "Disperate, mortali! Il vostro destino è giunto!", "." },
  ["f0c5f7363c198e1d"] = { "Non provare a teletrasportarti in una delle città dei tuoi nemici. Non funzionerà: qui saremo anche tutti amici, ma a casa i vecchi rancori restano...", "." },
  ["f0d50494ebc80e7d"] = { "Niente può cambiare il passato, ma il tempo guarisce tutte le ferite. Grazie per avermi mostrato che è possibile, {name}. Ti auguro ogni bene.", "." },
  ["f0dc03d6b6a6e5c2"] = { "Questo è il mio dialogo di prova.", "." },
  ["f0dd3d186af29a38"] = { "Ah, vedo che ti affanni con reliquie del passato.", "." },
  ["f0df7132f88a3f9c"] = { "Hai imparato le basi della preparazione delle pozioni, ma per studiare oltre serve un impegno maggiore. Dimostra la tua dedizione svolgendo un compito per me.", "." },
  ["f0e6e97de87c1a84"] = { "Padre? Sei fiero di me ora? AHAH!", "." },
  ["f0f2f3813352d1d5"] = { "Avresti dovuto restartene a casa.", "." },
  ["f0fc524ee7f17edd"] = { "«Taurahe?»\n\nLa druida tauren ti guarda con aria speranzosa, ma è chiaro che non puoi comunicare con lei a parole. Senza perdersi d'animo, indica se stessa e sorride. Indica te e sorride di nuovo. Infine fa più volte cenno lungo il sentiero verso sud.\n\nForse ti sta indicando che più avanti lungo la strada c'è un druido con cui puoi parlare?", "." },
  ["f0fed102bec2e65b"] = { "Capo Bloodhoof, potrà sembrare una richiesta strana... ma ho un giovane protetto molto timido. Per lui sei un eroe, e mi ha chiesto di procurargli l'impronta del tuo zoccolo.", "." },
})
